### Forward a thread email
# @name inboxes/forward-thread-email
POST {{host}}/inboxes/{{inbox_id}}/threads/{{thread_id}}/emails/{{email_id}}/forward
Authorization: Bearer {{token}}
Idempotency-Key: {{Idempotency-Key}}
Content-Type: application/json
Accept: application/json

{
  "to": [
    "colleague@example.org"
  ],
  "cc": [
    "billing@acme.com"
  ],
  "bcc": [
    "records@acme.com"
  ],
  "html": "\u003Cp\u003EFlagging this refund request for you.\u003C/p\u003E",
  "text": "Flagging this refund request for you.",
  "subject": "Fwd: Refund for order 1041",
  "attachments": [
    {
      "content": "",
      "filename": "string",
      "path": "string",
      "content_type": "string",
      "content_id": "string"
    }
  ],
  "headers": {
    "X-Ticket-Id": "4821"
  }
}

